Here's how to test `DataFetcher` with modern MSTest patterns:

```csharp
[TestClass]
public sealed class DataFetcherTests
{
    private readonly TestContext _testContext;

    public DataFetcherTests(TestContext testContext)
    {
        _testContext = testContext;
    }

    [TestMethod]
    public async Task FetchAsync_SuccessfulResponse_ReturnsContent()
    {
        // Arrange
        var handler = new FakeHttpMessageHandler("hello world", HttpStatusCode.OK);
        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        // Act
        var result = await fetcher.FetchAsync("https://example.com/data",
            _testContext.CancellationToken);

        // Assert
        Assert.AreEqual("hello world", result);
    }

    [TestMethod]
    public async Task FetchAsync_NotFound_ThrowsHttpRequestException()
    {
        var handler = new FakeHttpMessageHandler("", HttpStatusCode.NotFound);
        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        await Assert.ThrowsExactlyAsync<HttpRequestException>(
            async () => await fetcher.FetchAsync("https://example.com/missing",
                _testContext.CancellationToken));
    }

    [TestMethod]
    [Timeout(5000)] // cancels TestContext.CancellationToken after 5s
    public async Task FetchAsync_WithTimeout_CompletesInTime()
    {
        var handler = new FakeHttpMessageHandler("fast", HttpStatusCode.OK);
        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        var result = await fetcher.FetchAsync("https://example.com",
            _testContext.CancellationToken);

        Assert.IsNotNull(result);
    }

    [TestMethod]
    public async Task FetchAsync_CancellationRequested_ThrowsTaskCanceledException()
    {
        var handler = new DelayedHttpMessageHandler(TimeSpan.FromSeconds(30));
        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);
        using var cts = new CancellationTokenSource();
        cts.Cancel(); // cancel immediately

        await Assert.ThrowsExactlyAsync<TaskCanceledException>(
            async () => await fetcher.FetchAsync("https://example.com",
                cts.Token));
    }
}
```

And the test fakes:

```csharp
// Returns a canned response
internal sealed class FakeHttpMessageHandler(string content, HttpStatusCode status)
    : HttpMessageHandler
{
    protected override Task<HttpResponseMessage> SendAsync(
        HttpRequestMessage request, CancellationToken cancellationToken)
    {
        cancellationToken.ThrowIfCancellationRequested();
        var response = new HttpResponseMessage(status)
        {
            Content = new StringContent(content),
        };
        return Task.FromResult(response);
    }
}

// Simulates a slow server — respects cancellation
internal sealed class DelayedHttpMessageHandler(TimeSpan delay) : HttpMessageHandler
{
    protected override async Task<HttpResponseMessage> SendAsync(
        HttpRequestMessage request, CancellationToken cancellationToken)
    {
        await Task.Delay(delay, cancellationToken);
        return new HttpResponseMessage(HttpStatusCode.OK);
    }
}
```

**Key patterns demonstrated:**

1. **`TestContext` via constructor injection** — enables `readonly` field, works with nullability
2. **`_testContext.CancellationToken`** — flows the framework's token into async calls so `[Timeout]` is cooperative (fixes MSTEST0045/0049)
3. **`Assert.ThrowsExactlyAsync<T>`** — modern async exception testing (not `[ExpectedException]`)
4. **`[Timeout(5000)]`** — cancels `TestContext.CancellationToken` after 5s, which propagates through your `FetchAsync` call
5. **Custom `CancellationTokenSource`** — for testing your code's cancellation behavior independent of the framework timeout
6. **Fake `HttpMessageHandler`** — avoids real HTTP calls; no mocking library needed
